function machineTexture(c,n,color,x,y,r,mat){const L=n.visual.level,ink=kitAlpha(n.e.palette.detail,.32),shine=kitAlpha(color,.7);c.save();const step=L?5:10;
 if(['painted-metal','brushed-metal','chrome','glass'].includes(mat)){const a=localLight(c,n)*Math.PI/180,g=c.createLinearGradient(x-r,y-r,x+r,y+r);g.addColorStop(0,kitAlpha(color,0));g.addColorStop(mat==='chrome'?.35:.4,kitAlpha(n.e.palette.underside,.7));g.addColorStop(.48,kitAlpha(color,0));g.addColorStop(.7,kitAlpha(n.e.palette.underside,mat==='chrome'?.5:.12));g.addColorStop(1,kitAlpha(color,0));c.fillStyle=g;c.fillRect(x-r*1.5,y-r*1.5,r*3,r*3);if(mat==='brushed-metal'&&L)for(let j=-r;j<r;j+=2)kitLine(c,n,[[x-r,y+j],[x+r,y+j+.4]],kitAlpha(n.e.palette.underside,.16),.3);if(mat==='glass')mPolyRaw(c,[[x-r,y-r],[x-r*.7,y-r],[x+r,y+r*.7],[x+r,y+r]],kitAlpha(n.e.palette.underside,.3))}
 else if(mat==='wood'){for(let j=-r;j<r;j+=step){c.beginPath();c.moveTo(x-r,y+j);c.bezierCurveTo(x-r*.2,y+j+Math.sin(j)*3,x+r*.3,y+j-3,x+r,y+j);c.strokeStyle=ink;c.lineWidth=.6;c.stroke()}}
 else if(mat==='stone'){for(let j=0;j<(L?16:6);j++){const xx=x+Math.sin(j*7.71)*r,yy=y+Math.cos(j*2.37)*r;c.fillStyle=kitAlpha(j%2?n.e.palette.detail:n.e.palette.underside,.14);c.beginPath();c.ellipse(xx,yy,Math.max(.4,r*.12),Math.max(.3,r*.055),j,0,TAU);c.fill()}if(L){c.strokeStyle=ink;c.lineWidth=.5;c.beginPath();c.moveTo(x-r*.3,y-r);c.lineTo(x-r*.16,y-r*.2);c.lineTo(x-r*.4,y+r*.25);c.stroke()}}
 else if(mat==='brick'){for(let yy=-r;yy<r;yy+=step*1.4){const offset=(Math.floor((yy+r)/(step*1.4))%2)*step;c.strokeStyle=ink;c.lineWidth=.6;c.beginPath();c.moveTo(x-r,y+yy);c.lineTo(x+r,y+yy);c.stroke();for(let xx=-r+offset;xx<r;xx+=step*2.3){c.beginPath();c.moveTo(x+xx,y+yy);c.lineTo(x+xx+(mat==='stone'?1:0),y+yy+step*1.4);c.stroke()}}}
 else if(mat==='fabric'){for(let j=-r;j<r;j+=step){c.strokeStyle=ink;c.lineWidth=.45;c.beginPath();c.moveTo(x+j,y-r);c.lineTo(x+j,y+r);c.moveTo(x-r,y+j);c.lineTo(x+r,y+j);c.stroke()}}
 else if(mat==='rubber'){c.fillStyle=kitAlpha(n.e.palette.detail,.17);c.fillRect(x-r,y-r,r*2,r*2);if(L)for(let j=-r;j<r;j+=step){c.strokeStyle=shine;c.lineWidth=.45;c.beginPath();c.moveTo(x+j,y-r);c.lineTo(x+j+4,y+r);c.stroke()}}
 else if(mat==='emissive'){const g=c.createRadialGradient(x,y,0,x,y,Math.max(1,r));g.addColorStop(0,kitAlpha(n.e.palette.underside,.8));g.addColorStop(1,kitAlpha(color,0));c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2)}c.restore()}
